<script setup>
import { fonts, fontCss } from '../fonts.js';
import TextStyleProperties from './TextStyleProperties.vue';
import ShapeProperties from './ShapeProperties.vue';
import { reactive, ref, watch } from 'vue';
import { presets, visibleBlocks, blockLabel } from '../model.js';
import { Pencil, Copy, Trash2, Plus, Play } from 'lucide-vue-next';
const props=defineProps({studio:Object});const s=reactive(props.studio), section=ref('element');
watch(()=>s.selectionScope,value=>{section.value=value==='slides'?'slide':'element';});watch(()=>s.selected,value=>{if(value)section.value='element';});
const pixels=v=>Math.round(v*s.resolution.width/1920);
</script>
<template>
<aside class="inspector properties-panel"><button class="panel-resizer" @pointerdown="s.resizePanel($event,'inspectorWidth')" aria-label="Redimensionner les propriétés"></button>
 <div class="properties-heading"><strong>Propriétés</strong><span>Diapo {{s.index+1}}</span></div>
 <div class="inspector-tabs"><button v-for="[id,label] in [['element','Élément'],['slide','Diapo'],['style','Style']]" :key="id" :class="{active:section===id}" @click="section=id">{{label}}</button></div>
 <div class="inspector-body">
  <template v-if="section==='element'">
   <p v-if="!s.selected" class="field-help">{{s.selectedKeys.length?s.selectedKeys.length+' éléments sélectionnés. Supp pour supprimer.':'Clique sur un élément pour afficher ses propriétés.'}}</p><template v-if="s.selectedKeys.length>1"><details class="property-details" open><summary>Sélection · {{s.selectedKeys.length}} objets</summary><div class="position-grid"><label v-for="[key,name] in [['x','X · gauche'],['y','Y · haut'],['w','Largeur'],['h','Hauteur']]" :key="key">{{name}}<output>{{pixels(s.selectionBounds?.[key]||0)}} px</output></label></div><p class="field-help">Alt : cadre global et distances. Glisse un objet sélectionné pour déplacer l’ensemble.</p><button class="btn full" @click="s.groupObjects">Grouper · Ctrl G</button><button v-if="s.canUngroup" class="btn full" @click="s.ungroupObjects">Dissocier · Ctrl Maj G</button><button class="btn full" @click="s.duplicateSelected">Dupliquer la sélection</button><button class="btn full" @click="s.removeBlock">Supprimer la sélection</button></details></template><template v-if="s.selected"><label>Élément sélectionné<select v-model="s.selected" aria-label="Élément sélectionné"><option v-for="key in visibleBlocks(s.current)" :key="key" :value="key">{{blockLabel(s.current,key)}}</option></select></label>
   <div class="element-actions"><button class="btn" v-if="!['image','shape'].includes(s.selectedType)" @click="s.workspace='editor';s.editSelected()"><Pencil :size="14"/>Éditer</button><button class="icon-btn" @click="s.duplicateSelected" title="Dupliquer l’élément (Ctrl D)" aria-label="Dupliquer l’élément"><Copy :size="16"/></button><button class="icon-btn" @click="s.removeBlock"  title="Supprimer l’élément" aria-label="Supprimer l’élément"><Trash2 :size="16"/></button></div>
   <details v-if="!['image','shape'].includes(s.selectedType)" class="property-details" open><summary>Style du texte</summary><div class="font-picker"><label>Police d’écriture<select v-model="s.position.font" @change="s.refreshTextStyle();s.fitSelection()" aria-label="Police de l’élément"><option v-if="!s.position.font" :value="undefined">{{s.selectedType==='code'?'Monospace système':'Arial'}} · actuelle</option><optgroup v-for="local in [true,false]" :key="String(local)" :label="local?'Polices système':'Google Fonts · incluses'"><option v-for="f in fonts.filter(f=>!!f.local===local&&(s.selectedType!=='code'||f.mono))" :key="f.id" :value="f.id">{{f.name}}</option></optgroup></select></label><p class="font-sample" :style="{fontFamily:fontCss(s.position.font,s.selectedType)}">{{s.selectedType==='code'?'public class Java { }':'Java · Aa Bb é è à 0123'}}</p><span v-if="s.fontLoading" class="field-help">Chargement de la police…</span></div>
   <TextStyleProperties v-if="!['image','shape'].includes(s.selectedType)" :value="s.selectedTextStyle" :font="s.position.font" :type="s.selectedType" @change="s.updateTextStyle"/></details>
   <details v-if="s.selectedType==='code'" class="property-details"><summary>Contenu du code</summary><label>Titre / nom de fichier<input v-model="s.codeCaption" maxlength="200" placeholder="Ex. HelloWorld.java · facultatif" aria-label="Titre de l’extrait de code"></label></details>
   <details v-if="s.selectedType==='image'" class="property-details" open><summary>Image et transparence</summary><label class="image-upload">{{s.current.elements[s.selected].src?'Remplacer l’image':'Importer une image'}}<input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" @change="s.uploadImage"></label><label>Cadrage<select v-model="s.current.elements[s.selected].fit"><option value="contain">Image entière</option><option value="cover">Remplir le cadre</option></select></label><label class="checkbox-label"><input type="checkbox" v-model="s.current.elements[s.selected].roundedCorners">Bords arrondis</label><label v-if="s.current.elements[s.selected].roundedCorners">Arrondi · {{s.current.elements[s.selected].cornerRadius??10}} %<input type="range" min="0" max="50" step="1" aria-label="Arrondi de l’image" :value="s.current.elements[s.selected].cornerRadius??10" @input="s.current.elements[s.selected].cornerRadius=Number($event.target.value)"></label><label class="checkbox-label"><input type="checkbox" v-model="s.current.elements[s.selected].background">Fond du thème derrière l’image</label><p class="field-help">PNG, WebP et SVG : transparence conservée. SVG autonome uniquement.</p></details>
   <details v-if="s.selectedType==='shape'" class="property-details" open><summary>Style de la forme</summary><ShapeProperties :shape="s.current.elements[s.selected]" :scale="s.resolution.width/1920"/><div v-if="s.selectedType==='shape'" class="shape-layer"><button class="btn" @click="s.moveLayer(false)">Arrière-plan</button><button class="btn" @click="s.moveLayer(true)">Premier plan</button></div></details>
   <details class="property-details" open><summary>Position et dimensions</summary>
   <div class="position-grid"><label v-for="[key,label] in [['x','Gauche'],['y','Haut'],['w','Largeur'],['h','Hauteur']]" :key="key">{{label}}<input type="number" :aria-label="label+' de l’élément'" :value="pixels(s.selectedType==='shape'?s.selectedBounds?.[key]||0:s.position[key]??(key==='h'?s.selectedBounds?.h||0:0))" min="0" :max="key==='y'||key==='h'?s.resolution.height:s.resolution.width" @change="s.setPosition(key,$event)"></label></div>
   <label>Rotation · degrés<input type="number" aria-label="Rotation de l’élément" :value="Math.round((s.position.rotation||0)*100)/100" step="1" @change="s.setRotation"><span class="field-help">Poignée ↻ près du coin · Maj : pas de 45°</span></label>
   <label v-if="!['image','shape'].includes(s.selectedType)">Taille du texte<input type="number" :value="pixels(s.position.size)" min="10" :max="pixels(260)" @change="s.setPosition('size',$event)"></label>
   <label v-if="s.selectedType==='text'" class="checkbox-label"><input type="checkbox" v-model="s.position.autoSize" @change="s.position.wrapWidth||=s.position.w;s.fitSelection()">Cadre ajusté au texte</label><label v-if="s.selectedType==='text'&&s.position.autoSize">Largeur maximale de ligne<input type="number" aria-label="Largeur maximale du texte" :value="pixels(s.position.wrapWidth)" min="80" :max="s.resolution.width" @change="s.position.wrapWidth=Math.max(80,Math.min(1920,Number($event.target.value)*1920/s.resolution.width));s.fitSelection()"></label><p v-if="s.selectedType==='text'" class="field-help">Un redimensionnement manuel passe en cadre fixe.</p></details>
   <details class="property-details"><summary>Apparition de l’élément</summary><label>Étape<input type="number" min="0" max="20" :value="s.current.fragments[s.selected].order" @change="s.updateFragment"></label><label>Animation<select v-model="s.current.fragments[s.selected].animation"><option value="fade">Fondu</option><option value="up">Montée douce</option><option value="zoom">Zoom léger</option><option value="none">Immédiate</option></select></label><p class="field-help">Étape 0 : visible au départ. Une pression sur Espace révèle chaque étape suivante.</p></details>
   <div class="editor-shortcuts"><span><kbd>Alt</kbd> distances · survoler un objet</span><span><kbd>← ↑ ↓ →</kbd> déplacer de 1 px</span><span><kbd>Maj</kbd> + flèches : 10 px</span><span><kbd>Ctrl D</kbd> dupliquer</span></div>
   </template><details class="property-details"><summary>Ajouter un élément</summary><div class="block-add"><button class="btn" @click="s.workspace='editor';s.addBlock('text')">Texte</button><button class="btn" @click="s.workspace='editor';s.addBlock('image')">Image</button><button class="btn" @click="s.workspace='editor';s.addBlock('code')">Code</button><button class="btn" @click="s.openShapes">Formes</button></div></details>
  </template>
  <template v-else-if="section==='slide'">
   <button class="btn full" @click="s.startPresentation(false)"><Play :size="14"/>Tester cette diapo</button>
   <label class="spaced">Disposition<select v-model="s.current.layout" @change="s.applyPreset(s.current.layout)"><option v-for="p in presets" :key="p.id" :value="p.id">{{p.name}}</option></select></label><button class="btn full" @click="s.applyPreset(s.current.layout)">Réappliquer la disposition</button><button v-if="s.canUndoLayout" class="btn full" @click="s.undoLayout">Annuler la recomposition</button>
   <div class="section-label spaced">TRANSITION</div><div class="exit-compact">{{s.exitLabel}}</div><label>Sortie vers<select v-model="s.current.exitDirection" aria-label="Direction de sortie"><option value="auto">Automatique · canvas</option><option value="left">← Gauche</option><option value="right">→ Droite</option><option value="up">↑ Haut</option><option value="down">↓ Bas</option></select></label><label>Durée<select v-model.number="s.transitionMs"><option :value="0">Immédiate</option><option :value="350">350 ms</option><option :value="650">650 ms</option><option :value="1000">1 seconde</option></select></label>
   <details class="property-details"><summary>Ordre des apparitions</summary><div class="fragment-list"><label v-for="key in visibleBlocks(s.current)" :key="key"><span>{{blockLabel(s.current,key)}}</span><input type="number" min="0" max="20" v-model.number="s.current.fragments[key].order" @change="s.current.fragments[key].order=Math.max(0,Math.min(20,Math.round(Number(s.current.fragments[key].order)||0)))"></label></div></details>
   <details class="property-details"><summary>Position sur le canvas</summary><div class="position-grid"><label>Colonne<input type="number" min="-10000" max="10000" v-model.number="s.gridDraft.x"></label><label>Ligne<input type="number" min="-10000" max="10000" v-model.number="s.gridDraft.y"></label></div><button class="btn full" @click="s.applyGrid">Appliquer</button></details>
  </template>
  <template v-else>
   <div class="section-label">THÈME DU PROJET</div><div class="theme-options"><button v-for="t in s.palette" :key="t.id" :class="{chosen:s.themeId===t.id}" @click="s.themeId=t.id"><i :style="{background:t.accent}"></i>{{t.name}}</button></div><p class="field-help">Commun à toutes les diapos et aux incrustations.</p>
   <details class="property-details" open><summary>Fond du diaporama</summary><label class="checkbox-label"><input type="checkbox" v-model="s.frame.gradient">Dégradé de fond</label><p class="field-help">Désactivé : couleur de fond unie du thème, sur toutes les diapos.</p></details>
   <details class="property-details"><summary>Habillage facultatif</summary><label class="checkbox-label"><input type="checkbox" v-model="s.frame.header">En-tête de diapo</label><label class="checkbox-label"><input type="checkbox" v-model="s.frame.footer">Pied de diapo</label></details>
  </template>
 </div>
</aside>
</template>
